.gzp-desk{
          pozadí:
            radiální gradient (120 % 70 % při 50 % 0 %, rgba (214,178,110,.05), transparentní 58 %),
            radiální gradient (130 % 100 % při 50 % 108 %, rgba (0,0,0,.34), transparentní 62 %),
            /* kresba dřeva — široce a nepravidelně rozmístěná (staré vlasové linie
               Vypadalo to jako samet) */
            opakující se lineární gradient (92 stupňů,
              rgba(0,0,0,.13) 0 3px,
              transparentní 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              transparentní 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              transparentní 43px 74px),
            /* spoje desek */
            opakující se lineární gradient (90 stupňů,
              rgba(0,0,0,.42) 0 2px,
              transparentní 2px 148px),
            lineární gradient (180 stupňů, #33261a 0 %, #291e13 52 %, #1c150d 100 %);
        }
        .gzp-under{
          pozice: absolutní;
          vložka: 0;
          pozadí: linear-gradient(180deg, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), vložka 0 0 0 1px rgba(120,90,36,.2);
          transform: otáčet(-1.15deg) translateY(5px);
        }
        .gzp-under--2{
          pozadí: linear-gradient(180deg, #e1d2ab 0%, #cfbd90 100%);
          transformovat: otáčet(.85deg) translateY(9px);
        }
